# Berkeley Protocol tests for "open source": could any member of the
# public observe, buy or request it, with no special legal status, no
# unauthorised access, and without interacting with a person?
def classify(unauthorised, special_status, asks_person, leaked):
    if unauthorised:
        return "off limits"
    if special_status or asks_person:
        return "closed source"
    if leaked:
        return "open source, restricted use"
    return "open source"

items = [  # (name, unauthorised, special_status, asks_person, leaked)
    ("company annual report",       False, False, False, False),
    ("court-ordered phone records", False, True,  False, False),
    ("chatting to an employee",     False, False, True,  False),
    ("dump of a hacked database",   False, False, False, True),
    ("guessing a staff password",   True,  False, False, False),
]
for name, *tests in items:
    print(f"{name:28s} {classify(*tests)}")

def gate(task):
    if not task["written_purpose"]:
        return "STOP: no documented requirement"
    if not task["mandate"]:
        return "STOP: nobody with authority asked for this"
    if task["targets_private_person"] and not task["lawful_basis"]:
        return "STOP: profiling a private person without a lawful basis"
    if task["needs_deception_or_login_bypass"]:
        return "STOP: needs misrepresentation or unauthorised access"
    if task["harm_if_wrong"] == "high" and not task["review"]:
        return "HOLD: get a second reviewer before publishing"
    return "GO: collect only what the requirement needs"

