import secrets, time

posts = {}
SAFE_KEYS = {"width", "height", "duration"}      # allowlist, not blocklist

def publish(text, media_meta):
    post_id = secrets.token_urlsafe(16)          # 128 random bits
    meta = {k: v for k, v in media_meta.items() if k in SAFE_KEYS}
    posts[post_id] = {"text": text, "meta": meta}
    return post_id

buckets = {}                                     # client -> (tokens, last)
def allow(client, rate=1.0, burst=10):
    tokens, last = buckets.get(client, (burst, time.monotonic()))
    now = time.monotonic()
    tokens = min(burst, tokens + (now - last) * rate)
    if tokens < 1:
        buckets[client] = (tokens, now); return False
    buckets[client] = (tokens - 1, now); return True

def get_post(post_id, client):
    if not allow(client):
        return "429 Too Many Requests"
    return posts.get(post_id)

ids = [publish(f"post {i}", {"gps": (12.34, 56.78), "width": 640})
       for i in range(5)]
print(get_post(ids[0], "reader")["meta"])
print(get_post("1001", "crawler"))               # guessing finds nothing
answers = [get_post(str(n), "crawler") for n in range(1002, 1102)]
print(answers.count("429 Too Many Requests"), "of 100 rapid guesses throttled")

